// Generated by Automated Quality Gate; review before merging.
const { total } = require('../../src/cart');

describe('cart.js - total()', () => {
  test('should calculate the total price for an array of items', () => {
    const items = [
      { price: 10, quantity: 2 },
      { price: 5, quantity: 1 }
    ];
    expect(total(items)).toBe(25);
  });

  test('should return 0 for an empty array', () => {
    expect(total([])).toBe(0);
  });

  test('should return 0 if quantities are 0', () => {
    const items = [{ price: 100, quantity: 0 }];
    expect(total(items)).toBe(0);
  });

  test('should handle items with decimal prices', () => {
    const items = [
      { price: 10.5, quantity: 2 },
      { price: 2.25, quantity: 4 }
    ];
    expect(total(items)).toBe(30);
  });

  test('should throw a TypeError if input is not an array', () => {
    const invalidInputs = [null, undefined, 'string', 123, {}];
    
    invalidInputs.forEach((input) => {
      expect(() => total(input)).toThrow(TypeError);
      expect(() => total(input)).toThrow('items must be an array');
    });
  });

  test('should handle large numbers correctly', () => {
    const items = [
      { price: 1000000, quantity: 10 },
      { price: 500000, quantity: 2 }
    ];
    expect(total(items)).toBe(11000000);
  });
});
